import{_ as n,C as r,o as l,c as o,am as t,j as i,a as p,E as s,w as h}from"./chunks/framework.CPf7Mz33.js";const v=JSON.parse('{"title":"MPI support","description":"","frontmatter":{},"headers":[],"relativePath":"man/advanced/mpi.md","filePath":"man/advanced/mpi.md","lastUpdated":null}'),d={name:"man/advanced/mpi.md"},u={class:"jldocstring custom-block",open:""};function c(m,e,k,g,y,_){const a=r("Badge");return l(),o("div",null,[e[4]||(e[4]=t('<h1 id="MPI-support" tabindex="-1">MPI support <a class="header-anchor" href="#MPI-support" aria-label="Permalink to &quot;MPI support {#MPI-support}&quot;">​</a></h1><p>There are a few adjustments needed before a script can be run in MPI.</p><h2 id="Setting-up-the-environment" tabindex="-1">Setting up the environment <a class="header-anchor" href="#Setting-up-the-environment" aria-label="Permalink to &quot;Setting up the environment {#Setting-up-the-environment}&quot;">​</a></h2><p>You will have to set up an environment with the following packages under Julia 1.9+: <code>PartitionedArrays</code>, <code>MPI</code>, and <code>JutulDarcy</code>. <code>HYPRE</code> is automatically installed. This is generally the best performing solver setup available, even if you are working in a shared memory environment.</p><h3 id="Writing-the-script" tabindex="-1">Writing the script <a class="header-anchor" href="#Writing-the-script" aria-label="Permalink to &quot;Writing the script {#Writing-the-script}&quot;">​</a></h3><p>Write your script as usual. The following options must then be set:</p><ul><li><p><a href="/JutulDarcy.jl/dev/man/highlevel#JutulDarcy.setup_reservoir_model"><code>setup_reservoir_model</code></a> should have the extra keyword argument <code>split_wells=true</code>. We also recommend keeping the default <code>backend=:csr</code> for the best performance.</p></li><li><p><a href="/JutulDarcy.jl/dev/man/highlevel#JutulDarcy.simulate_reservoir"><code>simulate_reservoir</code></a> or <a href="/JutulDarcy.jl/dev/man/highlevel#JutulDarcy.setup_reservoir_simulator"><code>setup_reservoir_simulator</code></a> should get the optional argument <code>mode = :mpi</code></p></li></ul><p>You must then run the file using the appropriate <code>mpiexec</code> as described in the MPI.jl documentation. Specialized functions will be called by <code>simulate_reservoir</code> when this is the case. We document them here, even if we recommend using the high level version of this interface:</p>',8)),i("details",u,[i("summary",null,[e[0]||(e[0]=i("a",{id:"JutulDarcy.simulate_reservoir_parray",href:"#JutulDarcy.simulate_reservoir_parray"},[i("span",{class:"jlbinding"},"JutulDarcy.simulate_reservoir_parray")],-1)),e[1]||(e[1]=p()),s(a,{type:"info",class:"jlObjectType jlFunction",text:"Function"})]),e[3]||(e[3]=t('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">simulate_reservoir_parray</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(case, mode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :mpi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; kwarg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Run simulation with parray. This function is primarily for testing. <a href="/JutulDarcy.jl/dev/man/highlevel#JutulDarcy.simulate_reservoir"><code>simulate_reservoir</code></a> can do the same job by passing the correct mode.</p>',2)),s(a,{type:"info",class:"source-link",text:"source"},{default:h(()=>[...e[2]||(e[2]=[i("a",{href:"https://github.com/sintefmath/JutulDarcy.jl/blob/f6653f5445c23351995adec4c03e0f9ee3f95ab6/src/ext/ext_partitionedarrays.jl#L1-L6",target:"_blank",rel:"noreferrer"},"source",-1)])]),_:1})]),e[5]||(e[5]=t('<h2 id="Checklist-for-running-in-MPI" tabindex="-1">Checklist for running in MPI <a class="header-anchor" href="#Checklist-for-running-in-MPI" aria-label="Permalink to &quot;Checklist for running in MPI {#Checklist-for-running-in-MPI}&quot;">​</a></h2><ul><li><p>Install and load the following packages at the top of your script: <code>PartitionedArrays, MPI, HYPRE</code></p></li><li><p>(Recommended): Put <code>MPI.Init()</code> at the top of your script</p></li><li><p>Make sure that <code>split_wells = true</code> is set in your model setup</p></li><li><p>Set <code>output_path</code> when running the simulation (otherwise the results will not be stored anywhere)</p></li><li><p>Set <code>mode=:mpi</code> when running the simulation.</p></li></ul><p>A few useful functions:</p><ul><li><p><code>MPI.install_mpiexecjl()</code> installs MPI that works &quot;out of the box&quot; with your current Julia setup</p></li><li><p><code>MPI.mpiexec()</code> gives you the path to the executable and all environment variables</p></li></ul><p>A typical command to launch a MPI script from within Julia:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # = 5 processes</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">script_to_run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;my_script.jl&quot;</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$(mpiexec())</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -n </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $(Base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">julia_cmd())</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> --project=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$(Base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">active_project())</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $script_to_run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Adding threads to the command will make JutulDarcy use both threads and processes</p><p>⚠️ <strong>Running a script in MPI means that all parts of the script will run on each process!</strong> If you want to do data analysis you will have to either wrap your code in <code>if MPI.Comm_rank(MPI.COMM_WORLD) == 0</code> or do the data analysis in serial (recommended).</p><h2 id="Limitations-of-running-in-MPI" tabindex="-1">Limitations of running in MPI <a class="header-anchor" href="#Limitations-of-running-in-MPI" aria-label="Permalink to &quot;Limitations of running in MPI {#Limitations-of-running-in-MPI}&quot;">​</a></h2><p>MPI can be cumbersome to use when compared to a standard Julia script, and the current implementation relies on the model being set up on each processor before subdivision. This can be quite memory intensive during startup.</p><p>You should be familiar with the MPI programming model to use this feature. See <a href="https://juliaparallel.org/MPI.jl/stable/" target="_blank" rel="noreferrer">MPI.jl</a> for more details, and how MPI is handled in Julia specifically.</p><p>For larger models, compiling the <a href="/JutulDarcy.jl/dev/man/advanced/compiled#Standalone-reservoir-simulator">Standalone reservoir simulator</a> is highly recommended.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>MPI consolidates results by writing files to disk. Unless you have a plan to work with the distributed states in-memory returned by the <code>simulate!</code> call, it is best to specify a <code>output_path</code> optional argument to <a href="/JutulDarcy.jl/dev/man/highlevel#JutulDarcy.setup_reservoir_simulator"><code>setup_reservoir_simulator</code></a>. After the simulation, that folder will contain output just as if you had run the case in serial.</p></div>',13))])}const b=n(d,[["render",c]]);export{v as __pageData,b as default};
